package notifications

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/ayn2op/discordo/internal/config"
	"github.com/ebitengine/oto/v3"
	"github.com/gen2brain/beeep"
	"github.com/hajimehoshi/go-mp3"
	"github.com/hajimehoshi/go-vorbis"
)

var audioMutex sync.Mutex // Prevent multiple audio notifications from playing simultaneously

func sendDesktopNotification(title string, message string, image string, playSound bool, duration int) error {
	if err := beeep.Notify(title, message, image); err != nil {
		return err
	}

	if playSound {
		cfg, err := config.Load(config.DefaultPath())
		if err != nil {
			return beeep.Beep(beeep.DefaultFreq, duration)
		}

		soundFile := cfg.Notifications.Sound.File
		if soundFile != "" {
			if err := playSoundFile(soundFile); err == nil {
				return nil
			}
		}

		return beeep.Beep(beeep.DefaultFreq, duration)
	}

	return nil
}

func playSoundFile(filePath string) error {
	// Use mutex to prevent multiple audio notifications from playing simultaneously
	audioMutex.Lock()
	defer audioMutex.Unlock()

	if _, err := os.Stat(filePath); err != nil {
		return err
	}

	ext := strings.ToLower(filepath.Ext(filePath))
	file, err := os.Open(filePath)
	if err != nil {
		return err
	}
	defer file.Close()

	// Create audio context that will be closed when function exits
	ctx, ready, err := oto.NewContext(&oto.NewContextOptions{
		SampleRate:   44100,
		ChannelCount: 2,
		Format:       oto.FormatFloat32LE,
		PeriodSize:   512,  // Smaller buffer size to reduce latency
		Periods:      4,    // Number of buffers
	})
	if err != nil {
		return err
	}
	defer ctx.Close()  // Ensure context is closed when function returns
	<-ready

	var decoder interface {
		Read([]byte) (int, error)
	}

	switch ext {
	case ".mp3":
		mp3Decoder, err := mp3.NewDecoder(file)
		if err != nil {
			return err
		}
		decoder = mp3Decoder
	case ".ogg", ".oga":
		oggDecoder, _, _, err := vorbis.Decode(file)
		if err != nil {
			return err
		}
		decoder = oggDecoder
	default:
		// For unsupported formats, close the file and return an error to trigger fallback
		return fmt.Errorf("unsupported audio format: %s", ext)
	}

	player := ctx.NewPlayer(decoder)
	defer player.Close()  // Ensure player is closed when function returns

	player.Play()

	// Use a non-blocking approach with a timeout
	// Since this runs in the same thread as the UI, we don't want to block for too long
	for i := 0; i < 100; i++ { // Limit the wait to prevent indefinite blocking
		if !player.IsPlaying() {
			break
		}
		// Brief sleep to yield to other processes
		select {
		case <-time.After(50 * time.Millisecond):
			// Continue checking
		}
	}

	// Don't call player.Close() here since we already defer it above
	return nil
}

